function validPalindrome(s) {
  const isP = t => t === [...t].reverse().join("");
  if (isP(s)) return true;
  if (s.length > 300) {
    let i = 0, j = s.length - 1; while (s[i] === s[j]) { i++; j--; }
    return isP(s.slice(i + 1, j + 1)) || isP(s.slice(i, j));
  }
  for (let k = 0; k < s.length; k++) if (isP(s.slice(0, k) + s.slice(k + 1))) return true;
  return false;
}
